<script id="rampart-strategy">
function createStrategy() {
  const buildOrder = [
    [3, "lance"], [0, "bolt"], [6, "frost"], [5, "flak"],
    [4, "cannon"], [8, "lance"], [10, "flak"], [2, "cannon"],
    [12, "cannon"], [14, "flak"], [1, "frost"], [7, "lance"],
    [9, "lance"], [11, "cannon"], [13, "bolt"], [15, "bolt"]
  ];
  const costs = { bolt: 50, cannon: 90, frost: 70, lance: 120, flak: 80 };
  const upgradeOrder = [3, 8, 5, 10, 4, 12, 7, 9, 2, 11, 14, 6, 0, 1, 13, 15];
  return {
    plan(s) {
      const actions = [];
      let gold = s.gold;
      for (let i = 0; i < buildOrder.length; i++) {
        const slot = buildOrder[i][0];
        const type = buildOrder[i][1];
        if (!s.slots[slot].turret && gold >= costs[type]) {
          actions.push({ op: "build", slot, type });
          gold -= costs[type];
        }
      }
      for (let tier = 1; tier < 3; tier++) {
        for (let i = 0; i < upgradeOrder.length; i++) {
          const slot = upgradeOrder[i];
          const t = s.slots[slot].turret;
          if (t && t.tier === tier) {
            const cost = costs[t.type] * tier;
            if (gold >= cost) {
              actions.push({ op: "upgrade", slot });
              gold -= cost;
            }
          }
        }
      }
      return actions;
    },
    target(t, candidates) {
      let best = candidates[0];
      let bestScore = -Infinity;
      for (let i = 0; i < candidates.length; i++) {
        const e = candidates[i];
        let score = 100000 - e.remaining;
        if (e.type === "mender") score += t.type === "frost" ? 10000 : 1000000;
        if (t.type === "lance") {
          score += e.hp * 8 + e.armor * 1000;
          if (e.type === "brute") score += 500000;
        } else if (t.type === "cannon") {
          let crowd = 0;
          for (let j = 0; j < candidates.length; j++) {
            const o = candidates[j];
            const dx = o.x - e.x, dy = o.y - e.y;
            if (!o.air && dx * dx + dy * dy <= 8100) crowd++;
          }
          score += crowd * 200000 - e.armor * 5000;
        } else if (t.type === "frost") {
          score = e.remaining + e.speed * 1000 + (e.slowed ? 0 : 500000);
          if (e.type === "mender") score += 1000000;
        } else if (t.type === "flak") {
          score += e.hp * 2;
        }
        if (score > bestScore) {
          bestScore = score;
          best = e;
        }
      }
      return best.id;
    }
  };
}
